deleted_at IS NULL

    AND (public_id LIKE CONCAT('%',#{keyword},'%') OR title LIKE CONCAT('%',#{keyword},'%')
         OR contact LIKE CONCAT('%',#{keyword},'%'))

AND status = #{status}
AND assignee_id = #{assigneeId}
AND created_at >= #{from}
AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
